e="{{ $entryIndex }}"><button class="btn btn-xs btn-success"><i class="fa fa-check"></i> 处理当前明细</button></form>@else — @endif</td></tr>@endforeach</tbody></table></td><td><strong>${{ number_format((float)$item->total_amount,2) }}</strong></td><td><span class="status-pill {{ $item->status }}">{{ $item->statusLabel() }}</span><br><small>已处理 {{ $processedEntryCount }}/{{ $entryList->count() }}</small></td><td>{{ $item->processed_by_name?:'—' }}@if($item->processed_at)<br><small>{{ $item->processed_at->format('Y-m-d H:i') }}</small>@endif</td></tr>@empty<tr><td colspan="7" class="text-center text-muted">暂无数据</td></tr>@endforelse</tbody></table></div>@if($submissions->hasPages())<div class="box-footer">{{ $submissions->links() }}</div>@endif</div></section>
