<script>(function($){var groups=@json($todayRechargeGroups),modal=$('#rechargeDetailModal'),confirmModal=$('#rechargeSendConfirmModal'),title=document.getElementById('rechargeDetailTitle'),body=document.getElementById('rechargeDetailBody'),selectAll=document.getElementById('rechargeSelectAll'),processButton=document.getElementById('rechargeProcessSelected'),form=document.getElementById('rechargeBatchProcessForm'),selected=[];function esc(value){return $('<div>').text(value==null?'':String(value)).html()}function money(value){return '$'+Number(value||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}function checked(){return Array.prototype.slice.call(body.querySelectorAll('.recharge-record-check:checked'))}function refresh(){var available=body.querySelectorAll('.recharge-record-check').length,list=checked();processButton.disabled=list.length===0;processButton.innerHTML='<i class="fa fa-check-square-o"></i> 处理选中（'+list.length+'）并发送消息';selectAll.checked=available>0&&list.length===available;selectAll.indeterminate=list.length>0&&list.length<available}document.addEventListener('click',function(event){var button=event.target.closest('[data-recharge-group]');if(!button)return;var group=groups[Number(button.getAttribute('data-recharge-group'))];if(!group)return;title.innerHTML='<small>充值明细 · {{ $today }}</small>'+esc(group.media)+' - '+esc(group.agency)+'（'+Number(group.percentage).toFixed(1)+'%）';var html='<div class="recharge-detail-summary"><div><span>填写人数</span><strong>'+group.people_count+'</strong></div><div><span>明细条数</span><strong>'+group.entry_count+'</strong></div><div><span>合计金额</span><strong>'+money(group.amount)+'</strong></div></div><div class="recharge-detail-list">';if(!group.details.length)html+='<div class="recharge-detail-empty"><i class="fa fa-inbox fa-2x"></i><br><br>今天暂无充值明细</div>';group.details.forEach(function(detail){var pending=detail.status!=='processed',value=detail.submission_id+':'+detail.entry_index;html+='<div class="recharge-detail-item '+(pending?'':'is-processed')+'"><div class="recharge-detail-head"><div class="recharge-select">'+(pending?'<input type="checkbox" class="recharge-record-check" value="'+value+'">':'<i class="fa fa-check-circle text-success" title="已处理"></i>')+'</div><div style="flex:1"><div class="recharge-detail-person">'+esc(detail.operator_name)+'</div><div class="recharge-detail-meta">'+esc(detail.operation_department_name)+' · '+esc(detail.submitted_at)+(pending?' · 未处理':' · 已处理')+'</div></div><div class="recharge-detail-amount">'+money(detail.amount)+'</div></div><div class="recharge-detail-account"><div><span>账户名称</span><b>'+esc(detail.account_name)+'</b></div><div><span>账户编号</span><b>'+esc(detail.account_number)+'</b></div></div></div>'});html+='</div>';body.innerHTML=html;selectAll.checked=false;selectAll.indeterminate=false;refresh();modal.modal('show')});body.addEventListener('change',function(event){if(event.target.classList.contains('recharge-record-check'))refresh()});selectAll.addEventListener('change',function(){Array.prototype.forEach.call(body.querySelectorAll('.recharge-record-check'),function(box){box.checked=selectAll.checked});refresh()});processButton.addEventListener('click',function(){selected=checked();if(!selected.length)return;document.getElementById('rechargeConfirmCount').textContent=selected.length;document.getElementById('rechargeConfirmList').innerHTML=selected.map(function(box){var item=box.closest('.recharge-detail-item');return '<div>'+esc(item.querySelector('.recharge-detail-person').textContent)+' · '+esc(item.querySelectorAll('.recharge-detail-account b')[0].textContent)+' · '+esc(item.querySelector('.recharge-detail-amount').textContent)+'</div>'}).join('');confirmModal.modal('show')});document.getElementById('rechargeConfirmSend').addEventListener('click',function(){if(!selected.length)return;this.disabled=true;selected.forEach(function(box){var input=document.createElement('input');input.type='hidden';input.name='records[]';input.value=box.value;form.appendChild(input)});form.submit()})})(jQuery);</script>
